<?php
$r = $args['record']; $d = $r['data']; $issue = 'msc_comic_issue' === $r['type'];
$parent = $issue ? \MSC\Comics::relationship( $r, 'parent_comic' ) : null;
$arc = $issue ? \MSC\Comics::relationship( $r, 'story_arc' ) : null;
$page = $issue ? null : \MSC\Comics::issue_page( $r, $_GET );
?>
<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="<?php echo esc_url( get_post_type_archive_link( 'msc_comic_arc' === $r['type'] ? 'msc_comic_arc' : 'msc_comic' ) ); ?>"><?php echo 'msc_comic_arc' === $r['type'] ? 'Story Arcs' : 'Comic Books'; ?></a><?php if ( $parent ) { ?><a href="<?php echo esc_url( \MSC\Presentation::url( $parent ) ); ?>"><?php echo esc_html( $parent['data']['title'] ); ?></a><?php } ?><span><?php echo esc_html( $d['title'] ); ?></span></nav>
<section class="detail-hero comic-hero">
    <div class="hero-art"><div class="detail-art"><?php echo \MSC\Presentation::image( $r ); \MSC\Attribution::collect_image( $r ); ?></div></div>
    <div class="hero-copy"><p class="eyebrow"><?php echo esc_html( \MSC\Comics::singular( $r['type'] ) ); ?></p><h1><?php echo esc_html( $d['title'] ); ?></h1>
        <div class="comic-tags"><?php if ( $issue && isset( $d['issue_number'] ) && '' !== $d['issue_number'] ) { ?><span class="comic-issue-badge">Issue #<?php echo esc_html( ltrim( $d['issue_number'], '#' ) ); ?></span><?php } ?><?php if ( ! empty( $d['variant'] ) ) { ?><span><?php echo esc_html( $d['variant'] ); ?></span><?php } ?><?php if ( $arc ) { ?><a class="comic-arc-badge" href="<?php echo esc_url( \MSC\Presentation::url( $arc ) ); ?>"><?php echo esc_html( \MSC\Comics::arc_label( $r ) ); ?></a><?php } ?></div>
        <?php if ( 'msc_comic' === $r['type'] && ( $assigned = \MSC\Comics::assigned_arcs( $r ) ) ) { ?><div class="comic-tags" aria-label="Assigned story arcs"><strong>Story arcs</strong><?php foreach ( $assigned as $assigned_arc ) { ?><a class="comic-arc-badge" href="<?php echo esc_url( \MSC\Presentation::url( $assigned_arc ) ); ?>"><?php echo esc_html( $assigned_arc['data']['title'] ); ?></a><?php } ?></div><?php } ?>
        <?php msc_screen_chips( $r ); ?>
        <dl class="facts comic-facts"><?php foreach ( array( 'publisher' => 'Publisher', 'start_year' => 'First year', 'end_year' => 'Final year', 'volume' => 'Run / volume', 'release_date' => 'On-sale date', 'cover_date' => 'Cover date', 'page_count' => 'Pages', 'price' => 'Cover price', 'expected_issues' => 'Issues in arc' ) as $key => $label ) { if ( ! isset( $d[ $key ] ) || '' === $d[ $key ] ) { continue; } $value = 'release_date' === $key ? wp_date( 'M j, Y', strtotime( $d[ $key ] . ' 12:00:00 UTC' ), new DateTimeZone( 'UTC' ) ) : $d[ $key ]; ?><div><dt><?php echo esc_html( $label ); ?></dt><dd><?php echo esc_html( $value ); ?></dd></div><?php } ?></dl>
        <?php if ( $parent ) { ?><p class="comic-parent-link"><a href="<?php echo esc_url( \MSC\Presentation::url( $parent ) ); ?>#comic-issues">All issues of <?php echo esc_html( $parent['data']['title'] ); ?></a></p><?php } ?>
    </div>
</section>
<?php $has_credits = ! empty( $d['writers'] ) || ! empty( $d['artists'] ) || ! empty( $d['cover_artists'] ); $overview = msc_screen_overview( $r ); if ( trim( wp_strip_all_tags( $overview ) ) || $has_credits ) { ?>
<section class="story-section comic-story<?php echo $has_credits ? '' : ' comic-no-credits'; ?>"><div class="story-copy"><?php if ( trim( wp_strip_all_tags( $overview ) ) ) { ?><h2>Overview</h2><div class="catalog-description"><?php echo $overview; ?></div><?php } ?></div><?php if ( $has_credits ) { ?><aside class="details-panel"><p class="eyebrow">Credits</p><dl class="facts"><?php foreach ( array( 'writers' => 'Writers', 'artists' => 'Artists', 'cover_artists' => 'Cover artists' ) as $key => $label ) { if ( empty( $d[ $key ] ) ) { continue; } ?><div><dt><?php echo esc_html( $label ); ?></dt><dd><?php echo esc_html( implode( ', ', (array) $d[ $key ] ) ); ?></dd></div><?php } ?></dl></aside><?php } ?></section>
<?php } ?>
<?php if ( $page && ( $page['total'] || $page['arc'] ) ) { ?>
<section id="comic-issues" class="comic-browser" data-comic-browser="<?php echo esc_attr( $r['uuid'] ); ?>">
    <div class="section-heading"><h2><?php echo 'msc_comic_arc' === $r['type'] ? 'Reading order' : 'Issues'; ?></h2><span><?php echo esc_html( $page['total'] ); ?> published issues</span></div>
    <?php if ( $page['arcs'] ) { ?><nav class="comic-arc-filters" aria-label="Filter issues by story arc"><a data-comic-nav href="<?php echo esc_url( remove_query_arg( array( 'comic_arc', 'comic_page' ) ) . '#comic-issues' ); ?>"<?php echo ! $page['arc'] ? ' aria-current="page"' : ''; ?>>All issues</a><?php foreach ( $page['arcs'] as $uuid => $label ) { ?><a data-comic-nav href="<?php echo esc_url( add_query_arg( array( 'comic_arc' => $uuid, 'comic_page' => 1 ) ) . '#comic-issues' ); ?>"<?php echo $page['arc'] === $uuid ? ' aria-current="page"' : ''; ?>><?php echo esc_html( $label ); ?></a><?php } ?></nav><?php } ?>
    <ol class="comic-issue-list"><?php foreach ( $page['issues'] as $entry ) { $data = $entry['data']; $book = \MSC\Comics::relationship( $entry, 'parent_comic' ); $arc_text = \MSC\Comics::arc_label( $entry ); ?>
        <li><a href="<?php echo esc_url( \MSC\Presentation::url( $entry ) ); ?>"><span class="comic-list-number"><?php echo esc_html( 'msc_comic_arc' === $r['type'] || $page['arc'] ? ( isset( $data['arc_position'] ) ? 'Part ' . $data['arc_position'] : '—' ) : ( isset( $data['issue_number'] ) ? '#' . ltrim( $data['issue_number'], '#' ) : '—' ) ); ?></span><span class="comic-list-title"><strong><?php echo esc_html( $data['title'] ); ?></strong><?php if ( 'msc_comic_arc' === $r['type'] && $book ) { ?><small><?php echo esc_html( $book['data']['title'] . ( isset( $data['issue_number'] ) ? ' · Issue #' . ltrim( $data['issue_number'], '#' ) : '' ) ); ?></small><?php } elseif ( $arc_text ) { ?><small><?php echo esc_html( $arc_text ); ?></small><?php } ?></span><?php if ( ! empty( $data['release_date'] ) ) { ?><time datetime="<?php echo esc_attr( $data['release_date'] ); ?>"><?php echo esc_html( $data['release_date'] ); ?></time><?php } ?><span class="comic-row-arrow" aria-hidden="true"><?php echo msc_archive_arrow(); ?></span></a></li>
    <?php \MSC\Attribution::collect( $entry, array( 'title', 'issue_number', 'release_date' ) ); } ?></ol>
    <?php if ( ! $page['total'] ) { ?><p>No published issues are assigned to this story arc.</p><?php } ?>
    <?php if ( $page['pages'] > 1 ) { ?><nav class="comic-pagination" aria-label="Issue pages"><?php for ( $n = max( 1, $page['page'] - 2 ); $n <= min( $page['pages'], $page['page'] + 2 ); ++$n ) { ?><a data-comic-nav href="<?php echo esc_url( add_query_arg( 'comic_page', $n ) . '#comic-issues' ); ?>"<?php echo $n === $page['page'] ? ' aria-current="page"' : ''; ?>><?php echo esc_html( $n ); ?></a><?php } ?></nav><?php } ?>
</section>
<?php } ?>
